content.css:
.marmiton-visual {
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  overflow: hidden;
  background: #f8f6f1;
  color: #29352f;
  font: 14px 'Segoe UI', sans-serif;
}
.marmiton-visual * {
  box-sizing: border-box;
}
.marmiton-visual button {
  border: 1px solid #e3e5de;
  background: white;
  color: #29352f;
  border-radius: 8px;
  padding: 9px 14px;
  cursor: pointer;
  font: inherit;
}
.marmiton-visual button:disabled {
  opacity: 0.5;
  cursor: default;
}
.marmiton-visual [hidden] {
  display: none!important;
}
.marmiton-visual .local-toolbar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  border-bottom: 1px solid #e3e5de;
  flex-shrink: 0;
}
.marmiton-visual .local-toolbar span {
  flex: 1;
  color: #66736b;
  font-size: 12px;
}
.marmiton-visual .pairing {
  display: flex;
  gap: 10px;
  padding: 12px 20px;
}
.marmiton-visual .pairing input {
  flex: 1;
  min-width: 0;
  padding: 10px;
  border: 1px solid #ddd;
  border-radius: 8px;
}
.marmiton-visual .messages {
  flex: 1;
  min-height: 0;
  overflow: auto;
  padding: 20px 6%;
}
.marmiton-visual .welcome {
  text-align: center;
  padding: 24px 0;
}
.marmiton-visual .welcome h2 {
  font-size: 25px;
}
.marmiton-visual .welcome p {
  color: #66736b;
}
.marmiton-visual .welcome button {
  margin: 6px;
}
.marmiton-visual .message {
  padding: 14px 18px;
  line-height: 1.6;
  margin: 12px 0;
  border-radius: 14px;
  max-width: 94%;
  overflow-wrap: anywhere;
}
.marmiton-visual .user {
  background: #f3dfd5;
  margin-left: auto;
  width: fit-content;
  white-space: pre-wrap;
}
.marmiton-visual .assistant {
  background: white;
  border: 1px solid #e9e7df;
}
.marmiton-visual .prose {
  white-space: pre-wrap;
}
.marmiton-visual .typing-indicator {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 26px;
  padding: 3px 0;
}
.marmiton-visual .typing-indicator span {
  width: 6px;
  height: 6px;
  background: #78877d;
  border-radius: 50%;
  animation: marmiton-dot 1.1s ease-in-out infinite;
}
.marmiton-visual .typing-indicator span:nth-child(2) {
  animation-delay: 0.15s;
}
.marmiton-visual .typing-indicator span:nth-child(3) {
  animation-delay: 0.3s;
}
@media (prefers-reduced-motion: reduce) {
  .marmiton-visual .typing-indicator span {
    animation: none;
    opacity: 0.7;
  }
}
.marmiton-visual details {
  font-size: 11px;
  color: #66736b;
  margin-top: 12px;
  overflow: auto;
}
.marmiton-visual table {
  border-collapse: collapse;
}
.marmiton-visual td,
.marmiton-visual th {
  padding: 5px 10px;
  text-align: left;
  border-bottom: 1px solid #eee;
}
.marmiton-visual .composer {
  flex-shrink: 0;
  padding: 12px 6% 16px;
  border-top: 1px solid #e3e5de;
  display: flex;
  gap: 12px;
  align-items: center;
}
.marmiton-visual textarea {
  flex: 1;
  min-width: 0;
  resize: none;
  border: 1px solid #ddd;
  border-radius: 12px;
  background: white;
  padding: 12px;
  font: inherit;
  color: inherit;
}
.marmiton-visual .actions {
  display: flex;
  gap: 8px;
}
.marmiton-visual .actions button:last-child {
  background: #db4b38;
  color: white;
  border-color: #db4b38;
}
@keyframes marmiton-dot {
  0%,
  70%,
  100% {
    opacity: 0.35;
    transform: translateY(0);
  }
  35% {
    opacity: 1;
    transform: translateY(-3px);
  }
}
